window.TopicPhoto = (() => {
  const P = window.TOPIC_PHOTOS || {};
  // first match wins; tested against headline + summary + place
  const RULES = [
    [/\b(bitcoin|crypto|ether(eum)?|stablecoin|blockchain|token)\b/i, 'bitcoin cryptocurrency'],
    [/\b(chip|semiconductor|nvidia|tsmc|amd|intel|wafer)\b/i, 'semiconductor chip'],
    [/\b(ai|artificial intelligence|openai|chatbot|model)\b/i, 'artificial intelligence robot'],
    [/\b(data cent(er|re)s?|cloud|server)\b/i, 'data center servers'],
    [/\b(cyber|hack|ransomware|breach)\b/i, 'cyber security'],
    [/\b(smartphone|iphone|apple|samsung)\b/i, 'smartphone'],
    [/\b(5g|telecom|mobile operator|broadband)\b/i, 'telecom tower 5g'],
    [/\b(electric vehicle|ev|tesla|battery|charging)\b/i, 'electric car charging'],
    [/\b(car|auto(maker)?|vehicle|gm|ford|toyota|volkswagen)\b/i, 'car factory'],
    [/\b(drone|military|defen[cs]e|army|missile|weapon|navy|vessel|warship)\b/i, 'parliament government building'],
    [/\b(airline|airport|aviation|boeing|airbus|flight)\b/i, 'airplane airport'],
    [/\b(oil|crude|opec|brent|refiner)\w*/i, 'oil refinery'],
    [/\b(tanker|shipping|freight rate)\b/i, 'oil tanker ship'],
    [/\b(lng|natural gas|gas pipeline|pipeline)\b/i, 'gas pipeline'],
    [/\b(solar)\b/i, 'solar panels'], [/\b(wind (farm|power|turbine))\b/i, 'wind turbines'],
    [/\b(hydro|dam)\b/i, 'hydroelectric dam'], [/\b(power plant|electricity|grid|nuclear)\b/i, 'power plant'],
    [/\b(gold)\b/i, 'gold bars'], [/\b(copper|lithium|nickel|cobalt|mineral|rare earth)s?\b/i, 'copper mine'],
    [/\b(mining|miner|mine)\b/i, 'mining truck'], [/\b(steel|iron ore|aluminium|aluminum)\b/i, 'steel factory'],
    [/\b(cocoa|chocolate)\b/i, 'cocoa beans'], [/\b(coffee)\b/i, 'coffee beans'], [/\b(tea)\b/i, 'tea plantation'],
    [/\b(wheat|grain|harvest|crop)s?\b/i, 'wheat field harvest'], [/\b(rice)\b/i, 'rice field'], [/\b(palm oil)\b/i, 'palm oil plantation'],
    [/\b(cotton|cashew)\b/i, 'cotton field'], [/\b(cattle|beef|livestock|dairy)\b/i, 'cattle ranch'], [/\b(wine|vineyard)\b/i, 'vineyard grapes'],
    [/\b(beer|brewer)\w*/i, 'beer brewery'], [/\b(farm|agricultur)\w*/i, 'farm tractor'], [/\b(fish(ing|eries)?)\b/i, 'fishing boats harbour'],
    [/\b(textile|garment|apparel)\b/i, 'textile factory'], [/\b(luxury|fashion)\b/i, 'luxury fashion'],
    [/\b(drug|pharma\w*|vaccine|biotech|health)\b/i, 'pharmaceutical laboratory'],
    [/\b(port|container|export|import|tariff|trade)s?\b/i, 'container port'],
    [/\b(logistic|warehouse|e-?commerce)\w*/i, 'warehouse logistics'], [/\b(rail(way)?|train)\b/i, 'freight train'],
    [/\b(truck|highway|road)\b/i, 'cargo trucks highway'], [/\b(bridge|infrastructure|construction)\b/i, 'highway bridge construction'],
    [/\b(housing|property|real estate|mortgage|home ?builder)\b/i, 'housing construction'],
    [/\b(hotel|touris\w*|travel)\b/i, 'hotel tourism'], [/\b(retail|store|consumer|shopper)s?\b/i, 'shopping retail store'],
    [/\b(supermarket|grocer\w*|food price)\b/i, 'supermarket groceries'], [/\b(satellite|space|rocket)\b/i, 'satellite space rocket'],
    [/\b(central bank|interest rate|rate (cut|hike)|fed|ecb|monetary)\b/i, 'central bank building'],
    [/\b(stock exchange|ipo|listing)\b/i, 'stock exchange building'],
    [/\b(shares?|stocks?|index|nasdaq|dow|s&p|market)\b/i, 'stock market trading screen'],
    [/\b(bank|lender|loan|credit)s?\b/i, 'bank building'],
    [/\b(budget|tax|debt|bond|inflation|currency|remittance|receipts)\b/i, 'banknotes money'],
    [/\b(factory|manufactur\w*|plant|industrial)\b/i, 'factory workers'],
    [/\b(acqui\w*|merger|deal|ceo|board|shareholder)s?\b/i, 'office meeting'],
    [/\b(president|minister|government|parliament|election|sanction|party|politburo|talks|summit|council)\b/i, 'parliament government building'],
  ];
  const BY_CAT = { economy: 'banknotes money', companies: 'office meeting', markets: 'stock market trading screen', geopolitics: 'parliament government building', commodities: 'container port', technology: 'data center servers', crypto: 'bitcoin cryptocurrency' };
  const hash = s => { let h = 2166136261; for (const ch of String(s)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return h >>> 0; };
  function pick(id, text, cat) {
    let topic = null; for (const [re, t] of RULES) if (P[t] && re.test(text || '')) { topic = t; break; }
    if (!topic) topic = P[BY_CAT[cat]] ? BY_CAT[cat] : 'city skyline business district';
    const list = P[topic]; if (!list || !list.length) return null;
    const [file, credit] = list[hash(id || text) % list.length].split('|');
    return { file: 'photos/' + file, src: 'assets/globe/photos/' + file, credit: credit || 'Pixabay', alt: topic, source: 'Pixabay', kind: 'topic' };
  }
  return { pick };
})();

export const pickTopicPhoto = (...a) => window.TopicPhoto.pick(...a);
